-- id-based rows (non-null cod_imovel), dedupe by (id, geometry) where geometry is null for all id rows here
CREATE OR REPLACE TABLE id_rows_all AS
  SELECT * FROM list_classified WHERE cod_imovel IS NOT NULL;

CREATE OR REPLACE TABLE id_rows_dedup_groups AS
  SELECT cod_imovel, geom_wkt, count(*) AS n, min(rn) AS keep_rn
  FROM id_rows_all
  GROUP BY cod_imovel, geom_wkt;

SELECT count(*) AS n_id_rows FROM id_rows_all;
SELECT count(*) AS n_distinct_id_groups FROM id_rows_dedup_groups;
SELECT sum(n-1) AS duplicates_removed FROM id_rows_dedup_groups WHERE n>1;
SELECT * FROM id_rows_dedup_groups WHERE n>1;

-- check found in car
CREATE OR REPLACE TABLE id_resolved AS
  SELECT g.cod_imovel, (c.cod_imovel IS NOT NULL) AS found_in_car
  FROM id_rows_dedup_groups g
  LEFT JOIN (SELECT DISTINCT cod_imovel FROM car) c USING (cod_imovel);

SELECT count(*) AS total, sum(found_in_car::int) AS found, sum((NOT found_in_car)::int) AS missing FROM id_resolved;

