CREATE OR REPLACE TABLE listed_parcels AS
  SELECT c.cod_imovel, c.municipio, c.geometry
  FROM (SELECT DISTINCT cod_imovel FROM read_parquet('work/resolved_parcels.parquet')) r
  JOIN car c USING (cod_imovel);

SELECT count(*) FROM listed_parcels;

CREATE OR REPLACE TABLE envelope_tbl AS
  SELECT ST_Envelope(ST_Union_Agg(geometry)) AS env FROM listed_parcels;

SELECT ST_AsText(env) FROM envelope_tbl;

-- buffered dissolved union (25m) in EPSG:5880, transformed back to 4326
CREATE OR REPLACE TABLE listed_union_buffered AS
  SELECT ST_Transform(
           ST_Union_Agg(ST_Buffer(ST_Transform(geometry, 'EPSG:4326', 'EPSG:5880', true), 25.0)),
           'EPSG:5880', 'EPSG:4326', true
         ) AS geom
  FROM listed_parcels;

SELECT ST_Area(geom) FROM listed_union_buffered;

